import{_ as a,b as l,e as r,a7 as e}from"./chunks/framework.CFO60l-h.js";const g=JSON.parse('{"title":"保研时间线","description":"国新系推免从低年级到大四的时间线与关键节点。","frontmatter":{"title":"保研时间线","description":"国新系推免从低年级到大四的时间线与关键节点。","type":"baoyan-timeline","tags":["保研","时间线","推免"],"updated":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"baoyan/timeline.md","filePath":"baoyan/timeline.md","lastUpdated":null}'),i={name:"baoyan/timeline.md"};function o(n,t,d,s,h,c){return l(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="保研时间线" tabindex="-1">保研时间线 <a class="header-anchor" href="#保研时间线" aria-label="Permalink to &quot;保研时间线&quot;">​</a></h1><blockquote><p>以“推免（保研）”为主，交叉标注考研/留学。具体日期以当年通知为准。</p></blockquote><h2 id="低年级-打底" tabindex="-1">低年级：打底 <a class="header-anchor" href="#低年级-打底" aria-label="Permalink to &quot;低年级：打底&quot;">​</a></h2><ul><li><strong>绩点</strong>：从大一开始，绩点是推免综合排序里权重最高的部分。</li><li><strong>英语</strong>：本院国新方向六级 <strong>520</strong> 是硬门槛；不够就尽早重刷。</li><li><strong>科研分</strong>：关注“求是学术”（大创升级）、“小创”（创新杯）等能加科研分的项目，及时报名。</li><li><strong>素拓分</strong>：参加活动、志愿服务、学生工作，但不要为了加分做一堆讲不出收获的事。</li><li><strong>方向</strong>：大二下确定大致方向（国新/专硕/学硕/外保），再补对应短板。</li></ul><h2 id="大三-冲刺" tabindex="-1">大三：冲刺 <a class="header-anchor" href="#大三-冲刺" aria-label="Permalink to &quot;大三：冲刺&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>该做什么</th></tr></thead><tbody><tr><td>大三上</td><td>认真学习保绩点；“绩点是重中之重”</td></tr><tr><td>大三寒假</td><td>小创没获奖可再做一次；专业不扎实的开始读教材（《传播学教程》《新闻理论十讲》《范式与流派》等）</td></tr><tr><td>大三下</td><td>继续上课；系统复习专业课；练英语口语；准备成绩单/排名/简历母版</td></tr><tr><td>6–7 月</td><td>期末结束后投递目标院校、参加考试/夏令营</td></tr><tr><td>9 月</td><td>预推免/本校推免；确认资格与系统填报</td></tr><tr><td>10 月</td><td>推免系统确认；未上岸迅速切换考研/留学/秋招</td></tr></tbody></table><h2 id="专硕复习四阶段-2026-分享" tabindex="-1">专硕复习四阶段（2026 分享） <a class="header-anchor" href="#专硕复习四阶段-2026-分享" aria-label="Permalink to &quot;专硕复习四阶段（2026 分享）&quot;">​</a></h2><ol><li><strong>3–4 月 通读专业书</strong>：传播学以《范式与流派》为重点，《传播学教程》补充；新闻学《新闻学概论》；网络传播《网络传播概论》。</li><li><strong>5–6 月初 专题整理</strong>：按题型形成自己的答题框架；可用 AI 辅助提炼分论点与案例，但要自己改。</li><li><strong>后期 知识记忆 + 热点</strong>：积累学科热点与英语语料。</li><li><strong>面试训练</strong>：模拟面试，练即兴表达；英语不追求语法完美，重专业术语与观点清晰。</li></ol><h2 id="学硕-国新-外保的差异" tabindex="-1">学硕/国新/外保的差异 <a class="header-anchor" href="#学硕-国新-外保的差异" aria-label="Permalink to &quot;学硕/国新/外保的差异&quot;">​</a></h2><ul><li><strong>学硕（本院）</strong>：尽早启动复习；计划清单 + 复盘；面试重学术潜质与思维纵深。</li><li><strong>国新</strong>：提前做全流程模拟面试；项目经历要围绕兴趣与方向连贯呈现，形成“个人辨识度”。</li><li><strong>外保</strong>：学业成绩、科研经历、专业背景三要素；注意目标项目英语要求；论文重研究过程与逻辑，不只看是否发表。</li></ul><h2 id="现在该做什么" tabindex="-1">现在该做什么 <a class="header-anchor" href="#现在该做什么" aria-label="Permalink to &quot;现在该做什么&quot;">​</a></h2><ul><li>大一/大二：查绩点、六级、科研分；确定方向。</li><li>大三上：保绩点；准备材料母版。</li><li>大三下：复习 + 投递 + 模拟面试。</li><li>大四：确认结果；准备 plan B。</li></ul><div class="tip custom-block"><p class="custom-block-title">心态</p><p>把注意力拉回“今天能做的 1 件事”。保研是重要的事，但不是唯一的路；不要用别人的时间线惩罚自己。</p></div>',13)])])}const b=a(i,[["render",o]]);export{g as __pageData,b as default};
